<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import {
  useApiMonitoring,
  GROUPINGS,
  REFRESH_INTERVALS,
  DATE_PRESETS,
  METHODS,
  CHART_METRICS,
  TOP_SLOWEST,
  TOP_CLIENT_ROWS
} from './useApiMonitoring'
import { layout, observePanelWidth } from '../infra/useInfraLayout'
import ApiMonitoringChart from './ApiMonitoringChart.vue'

const {
  state, setFilter, applyFilters, applyPreset, clearFilters,
  loadDates, loadAll, setLive, setIntervalSeconds, setAllUsers,
  endpointRows, statusRows, chartRows, hasData, issues,
  filtersActive, activePreset, groupingLabel,
  socketEventRows, localNetworkRows, socketTotals, localNetworkTotals, clearClientLogs,
  fmtMs, fmtNum, fmtPct, fmtTimestamp, fmtClock, fmtDuration, latencyTone, statusTone,
  errorTone, TOP_ENDPOINTS
} = useApiMonitoring()

/* ── panel width tracking (this view lives in a resizable dockview panel) ─── */
const rootEl = ref(null)
let disposeLayout = null

/* ── derived ──────────────────────────────────────────────────────────────── */
const loading = computed(() => state.status === 'loading')
const endpointCount = computed(() => Object.keys(state.endpoints || {}).length)
const topEndpoints = computed(() => endpointRows.value.slice(0, TOP_ENDPOINTS))
const slowestCalls = computed(() => state.slowest.slice(0, TOP_SLOWEST))

/** Highest call count, used as the 100% of the status share bars. */
const maxCalls = computed(
  () => statusRows.value.reduce((max, row) => Math.max(max, Number(row.calls) || 0), 0)
)

function share(row) {
  if (!maxCalls.value) return 0
  return Math.round(((Number(row.calls) || 0) / maxCalls.value) * 100)
}

const kpis = computed(() => {
  const summary = state.summary || {}
  const calls = Number(summary.calls) || 0
  const worst = endpointRows.value[0]

  return [
    {
      id: 'calls',
      label: 'Calls',
      value: fmtNum(calls),
      sub: `${groupingLabel.value} · ${chartRows.value.length} buckets`
    },
    {
      id: 'error',
      label: 'Error rate',
      value: fmtPct(summary.error_rate),
      tone: errorTone(summary.error_rate),
      sub: `${fmtNum(summary.errors)} failed of ${fmtNum(calls)}`
    },
    {
      id: 'avg',
      label: 'Avg latency',
      value: fmtMs(summary.avg_duration_seconds),
      tone: latencyTone(summary.avg_duration_seconds),
      sub: `min ${fmtMs(summary.min_duration_seconds)}`
    },
    {
      id: 'p95',
      label: 'p95 latency',
      value: fmtMs(summary.p95_duration_seconds),
      tone: latencyTone(summary.p95_duration_seconds),
      sub: `max ${fmtMs(summary.max_duration_seconds)}`
    },
    {
      id: 'time',
      label: 'Total time',
      value: fmtDuration(summary.total_duration_seconds),
      sub: 'sum of the request time'
    },
    {
      id: 'endpoints',
      label: 'Endpoints',
      value: endpointCount.value,
      sub: worst ? `slowest: ${worst.path}` : 'no endpoint recorded'
    }
  ]
})

/* ── tone helpers ─────────────────────────────────────────────────────────── */
function toneText(tone) {
  return {
    success: 'text-success',
    warning: 'text-warning',
    error: 'text-error',
    info: 'text-info'
  }[tone] || ''
}

function rowClass(tone) {
  return {
    success: 'bg-success/10',
    warning: 'bg-warning/10',
    error: 'bg-error/10',
    info: 'bg-info/10'
  }[tone] || 'bg-base-300'
}

function meterClass(tone) {
  return {
    success: 'progress-success',
    warning: 'progress-warning',
    error: 'progress-error',
    info: 'progress-info'
  }[tone] || 'progress-primary'
}

function badgeClass(code) {
  return {
    success: 'badge-success',
    warning: 'badge-warning',
    error: 'badge-error',
    info: 'badge-info'
  }[statusTone(code)] || 'badge-ghost'
}

/* ── handlers ─────────────────────────────────────────────────────────────── */
function refresh() {
  return loadAll()
}

function onGroupingChange(event) {
  // `setFilter` bumps the revision (immediate redraw) and `applyFilters`
  // replaces the running round, so the new bucket size is fetched right away.
  setFilter({ grouping: event.target.value })
  applyFilters()
}

function onDate(key, event) {
  setFilter({ [key]: event.target.value })
  applyFilters()
}

function onMethod(event) {
  setFilter({ method: event.target.value })
  applyFilters()
}

function onPath(event) {
  setFilter({ path: event.target.value })
  applyFilters()
}

function onStatus(event) {
  setFilter({ statusCode: event.target.value })
  applyFilters()
}

function onMinDuration(event) {
  setFilter({ minDurationSeconds: event.target.value })
  applyFilters()
}

function onUser(event) {
  setFilter({ username: event.target.value })
  applyFilters()
}

function onProject(event) {
  setFilter({ projectName: event.target.value })
  applyFilters()
}

function onPreset(id) {
  applyPreset(id)
}

function onEndpointSelect(path) {
  // Clicking an endpoint narrows the whole view to it (same as the select).
  setFilter({ path })
  applyFilters()
}

function onSort(event) {
  state.sortBy = event.target.value
}

function onLive(event) {
  setLive(event.target.checked)
}

function onRefreshInterval(event) {
  setIntervalSeconds(event.target.value)
}

function onAllUsers(event) {
  setAllUsers(event.target.checked)
}

function onClearFilters() {
  clearFilters()
}

/* ── lifecycle ────────────────────────────────────────────────────────────── */
onMounted(async () => {
  disposeLayout = observePanelWidth(rootEl.value)
  // Data first (the panels render from it), then the available-dates hint.
  await loadAll()
  loadDates()
})

onBeforeUnmount(() => {
  if (disposeLayout) {
    disposeLayout()
    disposeLayout = null
  }
  // Never leave a timer running behind a closed panel; the live preference is
  // kept so the next mount resumes with the operator's choice.
  setLive(false)
})
</script>
</file_change>

## Summary of changes

| File | Change |
| --- | --- |
| `src/api/telemetry.js` | **New.** Bounded (300-entry) in-memory ring buffers + cumulative counters for socket events and local-network calls. Detects "local network" targets (same origin, `localhost`, RFC1918, `169.254.*`, `*.local/.lan/.internal`, single-label hosts). Stores only name/direction/size/timing — never payloads. |
| `src/api/socket.js` | Records `connect` / `disconnect` (with reason) / `connect_error` / `reconnect`, every inbound event (`onAny`, now also passing multi-arg events safely) and every `emit`, including **ack round-trip latency** when an ack callback is used, plus the "socket not connected" failure. |
| `src/api/connection.js` | Private `trackLocalCall()` wraps the axios promise of `get/del/post/put/delete` and records method, path, status and browser-measured latency. Returns the same promise — request/response chain unchanged. |
| `src/views/api-monitoring/useApiMonitoring.js` | Imports telemetry; adds `socketEvents`, `localNetworkCalls`, `socketTotals`, `localNetworkTotals`, `socketEventRows` (grouped by event), `localNetworkRows` (grouped by method+path, slowest first), `clearClientLogs`, `fmtClock`, `TOP_CLIENT_ROWS`; adds 3 diagnostic rules (socket offline / socket errors / local-network failures) and documents the two client-side sources in the module header. |
| `src/views/api-monitoring/ApiMonitoringView.vue` | Two new cards — **Socket events** (connection pill, sent/received/errors/ack, per-event table) and **Local network** (calls/failed/avg/>1s, per-endpoint table) — plus two header counters. Uses the existing card/table/badge/badge-tone patterns, `layout.compact` single-column fallback, `scope="col"` headers, `title`+`aria-label` on the clear buttons. |

**Design notes / trade-offs**
- The new sections are **browser-measured**, which is exactly the gap: the view already answers "how long did the server take?", the new cards answer "what did the socket and the LAN hop do?" (no double-counting, deduping is documented in the module header).
- Clear actions are per card (`eraser` icon) so the socket state pill never lies after a clear.
- No polling added: everything is reactive off `@/api/telemetry`, so the Live loop stays the only timer.
- If the backend later exposes stored socket/local-network records, the swap is localised: replace the two computeds (`socketEvents`, `localNetworkCalls`) with `apiLogsModule` calls — the view needs no change.

